INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42011, 'Daniel 2:31', 'Daniel', 2, 31, 'اے بادشاه سلامت تا په خوب کښې وليدل چې يوه لويه ځلېدونکې او حېرانوونکې مجسمه ستا په وړاندې ولاړه وه او هغه يروونکې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_31.mp3', '', 1761754199, 1761754199),
(42012, 'Daniel 2:32', 'Daniel', 2, 32, 'د دې مجسمې سر د خالصو سرو زرو نه جوړ شوے وو، د هغۀ سينه او لاسونه د سپينو زرو نه، د هغۀ ګېډه او پتونونه د زېړو نه جوړ وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_32.mp3', '', 1761754199, 1761754199),
(42013, 'Daniel 2:33', 'Daniel', 2, 33, 'د دې پنډۍ د اوسپنې، او د پښو څۀ حِصه د اوسپنې او څۀ حِصه د پخې شوې خاورې نه جوړه شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_33.mp3', '', 1761754199, 1761754199),
(42014, 'Daniel 2:34', 'Daniel', 2, 34, 'هرکله چې تا دې ته کتل، نو په دې وخت کښې د غرۀ نه يو لوئ کاڼے په خپله راجدا شو، خو د انسان په لاسونو نه. هغه د هغه مجسمې په پښو راپرېوتو کومې چې د اوسپنې او خاورو نه جوړې شوې وې او هغه يې ټوټه ټوټه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_34.mp3', '', 1761754199, 1761754199),
(42015, 'Daniel 2:35', 'Daniel', 2, 35, 'نو بيا اوسپنه، خاوره، زېړ، سپين زر او سرۀ زر ټول ټوټه ټوټه شو او داسې والوتل لکه څنګه چې په اوړى کښې بوس د غنمو په درمند کښې الوځى. هوا هغه ټول يوړل او هيڅ نښه يې پاتې نۀ شوه. خو هغه کاڼى کوم چې دا مجسمه وويشته هغې نه يو لوئ غر جوړ شو او ټوله زمکه يې ونيوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_35.mp3', '', 1761754199, 1761754199),
(42016, 'Daniel 2:36', 'Daniel', 2, 36, 'دا ستا خوب وو، او زۀ به يې اوس تعبير هم درته بيان کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_36.mp3', '', 1761754199, 1761754199),
(42017, 'Daniel 2:37', 'Daniel', 2, 37, 'تاسو، اے بادشاه سلامت، د ټولو بادشاهانو نه لوئ بادشاه يئ. آسمانى خُدائ پاک درته بادشاهى او قدرت، زور شان او شوکت درکړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_37.mp3', '', 1761754199, 1761754199),
(42018, 'Daniel 2:38', 'Daniel', 2, 38, 'هغۀ ستا لاسونو ته ټول انسانان او ځناور او د هوا مارغان حواله کړى دى. چرته چې هم دوئ اوسيږى، هغۀ تۀ په هغوئ ټولو حکمران مقرر کړے يې. او هغه د سرو زرو سر تۀ په خپله يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_38.mp3', '', 1761754199, 1761754199),
(42019, 'Daniel 2:39', 'Daniel', 2, 39, 'ستا نه وروستو، به يوه بله بادشاهى قائمه شى چې ستا د بادشاهۍ نه به کمزورې وى، او بيا به درېمه بادشاهى راشى، د زېړو به وى، او دا به په ټوله زمکه حکمرانى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_39.mp3', '', 1761754199, 1761754199),
(42020, 'Daniel 2:40', 'Daniel', 2, 40, 'په آخر کښې به بيا څلورمه بادشاهى راشى چې د اوسپنې په شان به مضبوطه وى ځکه چې اوسپنه هر څۀ ماتوى او ټوټه ټوټه کوى، نو بيا څنګه چې اوسپنه څيزونه ټوټه ټوټه کوى نو داسې به هغه نور ټول مات او ټوټه ټوټه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_40.mp3', '', 1761754199, 1761754199),
(42021, 'Daniel 2:41', 'Daniel', 2, 41, 'لکه څنګه چې تا وليدل چې د هغې د پښو او ګوتو څۀ حِصه د اوسپنې او څۀ حِصه د پخې خاورې نه جوړه وه نو دا به جدا شوے بادشاهت وى، خو بيا به هم په کښې څۀ نا څۀ د اوسپنې زور پاتې وى، څنګه چې تا اوسپنه خاورې سره يوځائ وليدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_41.mp3', '', 1761754199, 1761754199),
(42022, 'Daniel 2:42', 'Daniel', 2, 42, 'کۀ څۀ هم چې تا وليدل چې اوسپنه د خټې سره ګډه شوې وه، نو بيا به د دې بادشاهۍ څۀ حِصه طاقتوره او څۀ حِصه کمزورى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_42.mp3', '', 1761754199, 1761754199),
(42023, 'Daniel 2:43', 'Daniel', 2, 43, 'تاسو وليدل چې اوسپنه د خاورې سره يوځائ شوې وه، نو بيا به دغه شان د هغه بادشاهۍ خلق هم کوشش وکړى چې د يو بل سره په وادۀ کولو د يو بل ملاتړ جوړ شى، خو دوئ به په خپلو کښې په اتفاق نۀ شى لکه څنګه چې اوسپنه د خاورو سره يوځائ کېدلے نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_43.mp3', '', 1761754199, 1761754199),
(42024, 'Daniel 2:44', 'Daniel', 2, 44, 'د هغه بادشاهانو په زمانه کښې، به آسمانى خُدائ پاک داسې بادشاهى راولى چې هغه به هيڅکله نۀ ختميږى، نۀ به دا بل قوم نيولے شى. هغه به دا ټول بادشاهتونه مات کړى او ختم به يې کړى، خو دا به د تل دپاره پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_44.mp3', '', 1761754199, 1761754199),
(42025, 'Daniel 2:45', 'Daniel', 2, 45, 'دا د غرۀ نه د کاڼى د راجدا کېدلو د رويا تعبير دے، خو د انسانانو په لاسونو نه، هغه کاڼى چې اوسپنه، زېړ، خاوره، سپين زر او سرۀ زر يې ټوټه کړل. لوئ خُدائ پاک بادشاه ته دا ښودلى دى چې په راتلونکى وخت کښې به څۀ کيږى. دا خوب رښتيا او تعبير يې باورى دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_45.mp3', '', 1761754199, 1761754199),
(42026, 'Daniel 2:46', 'Daniel', 2, 46, 'نو بيا نبوکدنضر بادشاه د دانيال په وړاندې ټيټ شو او د هغۀ عزت يې وکړو او حکم يې وکړو چې هغۀ ته د غلو دانو او د خوشبو نذرانې وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_46.mp3', '', 1761754199, 1761754199),
(42027, 'Daniel 2:47', 'Daniel', 2, 47, 'بادشاه دانيال ته ووئيل، ”بې‌شکه ستا خُدائ پاک د ټولو معبودانو خُدائ پاک دے او د بادشاهانو مالِک دے او د رازونو ښکاره کوونکے دے. ځکه چې تا ته دا راز څرګند کړے شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_47.mp3', '', 1761754199, 1761754199),
(42028, 'Daniel 2:48', 'Daniel', 2, 48, 'بيا بادشاه دانيال ته لوئ مقام ورکړو، او ډيرې او ښکلې تحفې يې ورکړې. بادشاه هغه د بابل په ټوله صوبه باندې حکمران او د ټولو هوښيارانو مشر مقرر کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_48.mp3', '', 1761754199, 1761754199),
(42029, 'Daniel 2:49', 'Daniel', 2, 49, 'نو د دانيال په خواست سره بادشاه شدرک، ميشک، او عبدنجو د بابل د صوبې په انتظاميه کښې آفسران مقرر کړل، او په خپله دانيال په شاهى دربار کښې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel2_verse_49.mp3', '', 1761754199, 1761754199),
(42030, 'Deuteronomy 14:1', 'Deuteronomy', 14, 1, 'تاسو د خپل څښتن خدای اولادونه یئ. نو کله چې د مړو دپاره ژاړئ، خپل ځانونه مه غوڅوئ یا د خپل تندي ویښتان مه خرایئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_1.mp3', '', 1761754199, 1761754199),
(42031, 'Deuteronomy 14:2', 'Deuteronomy', 14, 2, 'تاسو د خپل څښتن خدای یئ، هغه د هغو ټولو قومونو څخه چې د ځمکې په مخ باندې ژوند کوي، تاسو د خپل قوم په توګه غوره کړي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_2.mp3', '', 1761754199, 1761754199),
(42032, 'Deuteronomy 14:3', 'Deuteronomy', 14, 3, 'هېڅ داسې شیان مه خورئ چې څښتن هغه حرام اعلان کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_3.mp3', '', 1761754199, 1761754199),
(42033, 'Deuteronomy 14:4', 'Deuteronomy', 14, 4, 'تاسو کولای شئ چې د دغو حیواناتو غوښه وخورئ: غویان، پسونه، وزې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_4.mp3', '', 1761754199, 1761754199),
(42034, 'Deuteronomy 14:5', 'Deuteronomy', 14, 5, 'هر ډول هوسۍ، غرني پسونه، ځنګلي وزې یا غرڅې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_5.mp3', '', 1761754199, 1761754199),
(42035, 'Deuteronomy 14:6', 'Deuteronomy', 14, 6, 'یعنې هر هغه حیوان چې خلاص سوم ولري او شخوند هم وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_6.mp3', '', 1761754199, 1761754199),
(42036, 'Deuteronomy 14:7', 'Deuteronomy', 14, 7, 'خو د هېڅ داسې حیوان غوښه باید ونه خوړل شي چې خلاص سومان نه لري او شخوند نه وهي. تاسو باید د اوښانو، سویو، یا د غرنیو سویو غوښه ونه خورئ. هغه باید ناپاک وګڼل شي، هغه شخوند وهي، خو خلاص سومان نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_7.mp3', '', 1761754199, 1761754199),
(42037, 'Deuteronomy 14:8', 'Deuteronomy', 14, 8, 'د خوګ غوښه مه خورئ. خوګ باید ناپاکه وګڼل شي، هغه خلاص سومان لري، خو شخوند نه وهي. د دغو حیواناتو غوښه مه خورئ او حتی د هغو مړو ته هم لاس مه وروړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_8.mp3', '', 1761754199, 1761754199),
(42038, 'Deuteronomy 14:9', 'Deuteronomy', 14, 9, 'تاسو کولای شئ هر ډول ماهیان چې وزرونه او پتري ولري وخورئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_9.mp3', '', 1761754199, 1761754199),
(42039, 'Deuteronomy 14:10', 'Deuteronomy', 14, 10, 'خو بل داسې شی چې په اوبو کې ژوند کوي او وزرونه او پتري ونه لري خوړل یې روا نه دي، هغه باید ناپاک وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_10.mp3', '', 1761754199, 1761754199),
(42040, 'Deuteronomy 14:11', 'Deuteronomy', 14, 11, 'تاسو کولای شئ چې هر ډول پاک مرغان وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_11.mp3', '', 1761754199, 1761754199),
(42041, 'Deuteronomy 14:19', 'Deuteronomy', 14, 19, 'ټول وزر لرونکي حشرات ناپاک دي، هغه مه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_19.mp3', '', 1761754199, 1761754199),
(42042, 'Deuteronomy 14:20', 'Deuteronomy', 14, 20, 'تاسو کولای شئ چې هر ډول پاک حشرات وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_20.mp3', '', 1761754199, 1761754199),
(42043, 'Deuteronomy 14:21', 'Deuteronomy', 14, 21, 'د داسې حیوان غوښه مه خورئ چې په خپل مرګ مړ شوی وي. تاسو کولای شئ چې دا هغو پردیو خلکو ته چې ستاسو په منځ کې اوسیږي، ورکړئ چې ویې خوري یا تاسو کولای شئ چې په نورو پردیو خلکو باندې یې خرڅه کړئ. خو تاسو د خپل څښتن خدای یئ، تاسو د هغه قوم یئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_21.mp3', '', 1761754199, 1761754199),
(42044, 'Deuteronomy 14:22', 'Deuteronomy', 14, 22, 'تاسو باید هر کال د خپلو پټیو د ټولو حاصلاتو لسمه برخه بېله کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_22.mp3', '', 1761754199, 1761754199),
(42045, 'Deuteronomy 14:23', 'Deuteronomy', 14, 23, 'بیا هغه ځای ته لاړ شئ چې ستاسو څښتن خدای به یې د خپل عبادت دپاره غوره کړي او هلته د هغه په حضور کې د خپلو غلو دانو، شرابو او زیتونو د تېلو عشر او د خپلو پادو او رمو لومړني زېږېدلي بچیان وخورئ. دا کار وکړئ ترڅو د تل دپاره خپل څښتن خدای ته درناوی کول زده کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_23.mp3', '', 1761754199, 1761754199),
(42046, 'Deuteronomy 14:24', 'Deuteronomy', 14, 24, 'که چېرې د عبادت ځای ستاسو د کور څخه ډېر لېرې وي چې د خپلو هغو محصولاتو عشر چې څښتن تاسو ته په کې برکت درکړی دی هلته وړلی نه شئ، بیا داسې وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_24.mp3', '', 1761754199, 1761754199),
(42047, 'Deuteronomy 14:25', 'Deuteronomy', 14, 25, 'چې خپل حاصلات خرڅ کړئ او د هغو پیسې هغه عبادت ځای ته یوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_25.mp3', '', 1761754199, 1761754199),
(42048, 'Deuteronomy 14:26', 'Deuteronomy', 14, 26, 'په هر شي باندې چې تاسو غواړئ دا پیسې مصرف کړئ یعنې په غواګانو، پسونو، وزو، شرابو باندې او د خپلو کورنیو سره یې هلته د خپل څښتن خدای په حضور کې وخورئ او خوشحالي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_26.mp3', '', 1761754199, 1761754199),
(42049, 'Deuteronomy 14:27', 'Deuteronomy', 14, 27, 'هغه لاویان مه هېروئ چې ستاسو په ښارونو کې اوسیږي، هغوی خپله ځمکه نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_27.mp3', '', 1761754199, 1761754199),
(42050, 'Deuteronomy 14:28', 'Deuteronomy', 14, 28, 'د هر درېم کال په پای کې د خپلو ټولو حاصلاتو عشر راوړئ او په خپلو ښارونو کې یې ذخیره کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_28.mp3', '', 1761754199, 1761754199),
(42051, 'Deuteronomy 14:29', 'Deuteronomy', 14, 29, 'هغه لاویانو ته چې ستاسو په منځ کې خپله ځمکه نه لري او همدارنګه هغو پردیو خلکو، یتیمانو او کونډو ته چې ستاسو په ښارونو کې اوسیږي ورکړئ چې ویې خوري او ورباندې ماړه شي. نو بیا به ستاسو څښتن خدای تاسو ته په ټولو کارونو کې برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy14_verse_29.mp3', '', 1761754199, 1761754199),
(42052, 'Deuteronomy 23:1', 'Deuteronomy', 23, 1, 'هېڅ داسې سړی چې خصي شوی وي یا د هغه تناسلي اله پرې کړل شوې وي د څښتن په قوم کې نه شي شاملېدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_1.mp3', '', 1761754199, 1761754199),
(42053, 'Deuteronomy 23:2', 'Deuteronomy', 23, 2, 'هېڅ داسې کس چې حرامي وي او د داسې کس اولاده حتی تر لسم نسله پورې د څښتن په قوم کې نه شي شاملېدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_2.mp3', '', 1761754199, 1761754199),
(42054, 'Deuteronomy 23:3', 'Deuteronomy', 23, 3, 'هېڅ عمونی یا موآبی او د هغوی اولاده حتی تر لسم نسله پورې د څښتن په قوم کې نه شي شاملېدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_3.mp3', '', 1761754199, 1761754199),
(42055, 'Deuteronomy 23:4', 'Deuteronomy', 23, 4, 'دا په دې سبب کله چې تاسو د مصر څخه راوتلئ، هغوی تاسو ته د ډوډۍ او اوبو د برابرولو څخه انکار وکړ او د بعور زوی بلعام یې چې په بین النهرین کې د فتور د ښار څخه ؤ، اجیر ونیوه چې په تاسو باندې لعنت ووایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_4.mp3', '', 1761754199, 1761754199),
(42056, 'Deuteronomy 23:5', 'Deuteronomy', 23, 5, 'خو ستاسو څښتن خدای به بلعام ته غوږ نه نیوه، د هغې په ځای یې لعنت په برکت بدل کړ، ځکه چې هغه ستاسو سره مینه درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_5.mp3', '', 1761754199, 1761754199),
(42057, 'Deuteronomy 23:6', 'Deuteronomy', 23, 6, 'تاسو او ستاسو راتلونکي نسلونه د هغو قومونو سره د هېڅ شي مرسته ونه کړئ او د هغوی نېکمرغي مه غواړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_6.mp3', '', 1761754199, 1761754199),
(42058, 'Deuteronomy 23:7', 'Deuteronomy', 23, 7, 'ادومیانو ته په سپکه سترګه مه ګورئ، ځکه چې هغوی ستاسو خپلوان دي. مصریانو ته هم په سپکه سترګه مه ګورئ، ځکه چې یو وخت تاسو د هغوی په خاوره کې اوسېدلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_7.mp3', '', 1761754199, 1761754199),
(42059, 'Deuteronomy 23:8', 'Deuteronomy', 23, 8, 'کېدای شي چې د هغوی لمسیان د څښتن په قوم کې شامل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_8.mp3', '', 1761754199, 1761754199),
(42060, 'Deuteronomy 23:9', 'Deuteronomy', 23, 9, 'کله چې تاسو د جنګ په وخت کې په کمپ کې یئ، باید د هر هغه شي څخه چې تاسو په مذهبي لحاظ ناپاکه کوي ځانونه وساتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_9.mp3', '', 1761754199, 1761754199),
(42061, 'Deuteronomy 23:10', 'Deuteronomy', 23, 10, 'که چېرې د شپې له خوا شیطان یو سړی وغولوي او له دې امله هغه ناپاک شي، هغه دې د کمپ څخه دباندې ووځي او هلته دې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_10.mp3', '', 1761754199, 1761754199),
(42062, 'Deuteronomy 23:11', 'Deuteronomy', 23, 11, 'هغه دې مازدیګر غسل وکړي او ماښام کولای شي چې بېرته کمپ ته راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_11.mp3', '', 1761754199, 1761754199),
(42063, 'Deuteronomy 23:12', 'Deuteronomy', 23, 12, 'د کمپ څخه دباندې یو داسې ځای جوړ کړئ چې د تشناب په توګه ورڅخه کار واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_12.mp3', '', 1761754199, 1761754199),
(42064, 'Deuteronomy 23:13', 'Deuteronomy', 23, 13, 'په خپلو سامانونو کې یو داسې شی ولرئ چې ځمکه ورباندې وکیندل شي. کله چې تاسو د اړتیا د رفع کولو دپاره ځئ، په هغه باندې یوه کنده وباسئ. بیا وروسته له دې چې خپل حاجت رفع کړئ، خپل غایطه مواد په هغې کندې کې ښخوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_13.mp3', '', 1761754199, 1761754199),
(42065, 'Deuteronomy 23:14', 'Deuteronomy', 23, 14, 'څرنګه چې ستاسو څښتن خدای ستاسو په کمپ کې ګرځي چې ستاسو ساتنه وکړي او په خپلو دښمنانو باندې بری درکړي، نو ستاسو کمپ باید سپېڅلی وي، ترڅو هغه ستاسو په منځ کې کوم خراب شی ونه ویني او ستاسو څخه مخ ونه ګرځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_14.mp3', '', 1761754199, 1761754199),
(42066, 'Deuteronomy 23:15', 'Deuteronomy', 23, 15, 'که چېرې یو غلام د خپل بادار څخه وتښتي او تاسو ته د پناه اخیستلو دپاره راشي، هغه بېرته خپل بادار ته په لاس مه ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_15.mp3', '', 1761754199, 1761754199),
(42067, 'Deuteronomy 23:16', 'Deuteronomy', 23, 16, 'هغه کولای شي ستاسو په هر ښار کې چې د هغه خوښه وي واوسیږي او تاسو باید د هغه سره بد چلند ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_16.mp3', '', 1761754199, 1761754199),
(42068, 'Deuteronomy 23:17', 'Deuteronomy', 23, 17, 'هېڅ اسراییلی سړی یا ښځه باید د عبادتځای بدلمنه نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_17.mp3', '', 1761754199, 1761754199),
(42069, 'Deuteronomy 23:18', 'Deuteronomy', 23, 18, 'همدارنګه هېڅ داسې پیسې چې په دې ډول ګټل شوې وي د نذر د ورکولو دپاره دې ستاسو د څښتن خدای کور ته رانه وړل شي. څښتن د عبادتځای د لواطت کارانو او بدلمنو څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_18.mp3', '', 1761754199, 1761754199),
(42070, 'Deuteronomy 23:19', 'Deuteronomy', 23, 19, 'کله چې تاسو یو اسراییلي ورور ته پیسې یا ډوډۍ یا بل شی په پور ورکړئ، د هغه څخه سود مه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_19.mp3', '', 1761754199, 1761754199),
(42071, 'Deuteronomy 23:20', 'Deuteronomy', 23, 20, 'تاسو کولای شئ چې د پردي کس څخه سود واخلئ، خو د اسراییلي څخه نه. دا کار وکړئ، نو ستاسو څښتن خدای به ستاسو په هر کار کې چې تاسو یې په هغه خاوره کې کوئ چې تاسو یې نیسئ، برکت واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_20.mp3', '', 1761754199, 1761754199),
(42072, 'Deuteronomy 23:21', 'Deuteronomy', 23, 21, 'کله چې تاسو خپل څښتن خدای ته نذر منئ، د خپلې وعدې په پوره کولو کې ځنډ مه کوئ، ځکه چې ستاسو څښتن خدای به ستاسو څخه وغواړي چې هغه وعده پوره کړئ. که نه، نو تاسو به ګناهکار وګڼل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_21.mp3', '', 1761754199, 1761754199),
(42073, 'Deuteronomy 23:22', 'Deuteronomy', 23, 22, 'دا کومه ګناه نه ده چې تاسو څښتن ته نذر ونه منئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_22.mp3', '', 1761754199, 1761754199),
(42074, 'Deuteronomy 23:23', 'Deuteronomy', 23, 23, 'څه چې تاسو ویلي دي هغه باید خامخا پوره کړئ، ځکه چې تاسو په خپله خوښه او په خپلې خولې څښتن ته نذر منلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_23.mp3', '', 1761754199, 1761754199),
(42075, 'Deuteronomy 23:24', 'Deuteronomy', 23, 24, 'کله چې تاسو د بل چا د انګورو باغ ته ورننوځئ، څومره انګور چې غواړئ خوړلی یې شئ، خو هغه باید په یو لوښي کې د خپل ځان سره یونسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_24.mp3', '', 1761754199, 1761754199),
(42076, 'Deuteronomy 23:25', 'Deuteronomy', 23, 25, 'کله چې تاسو د بل چا د غلو دانو پټي ته ورننوځئ، کولای شئ چې په خپلو لاسونو باندې وږي راټول کړئ او هغه وخورئ، خو هغه باید په لور باندې ونه رېبئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy23_verse_25.mp3', '', 1761754199, 1761754199),
(42077, 'Leviticus 2:1', 'Leviticus', 2, 1, 'کله چې ستاسو څخه څوک څښتن ته د غلې دانې نذرانه وړاندې کوي، هغه نذرانه دې د ښو اوړو څخه وي. په هغې باندې دې د زیتونو تېل توی کړي، قیمتي خوشبویي دې ورباندې واچوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_1.mp3', '', 1761754199, 1761754199),
(42078, 'Leviticus 2:2', 'Leviticus', 2, 2, 'او د هارون زامنو یعنې کاهنانو ته دې وروړي. کاهن دې د ټولې قیمتي خوشبویۍ سره د ښو اوړو څخه چې تېل ورسره ګډ دي، یو موټی راواخلي او هغه دې د یوې نمونې په توګه چې ټوله څښتن ته وړاندې کیږي، د قربانۍ په ځای باندې وسوځوي. دا یوه داسې نذرانه ده چې بوی یې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_2.mp3', '', 1761754199, 1761754199),
(42079, 'Leviticus 2:3', 'Leviticus', 2, 3, 'د غلې دانې پاتې نذرانه د کاهنانو ده، دا د هغو نذرانو یوه ډېره سپېڅلې برخه ده چې څښتن ته په اور باندې تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_3.mp3', '', 1761754199, 1761754199),
(42080, 'Leviticus 2:4', 'Leviticus', 2, 4, 'که چېرې نذرانه داسې ډوډۍ وي چې په تنور کې پخه شوې وي، باید فطیره وي. هغه باید د داسې ښو اوړو څخه تیاره شوې وي چې د زیتونو تېل ورسره ګډ وي یا نرۍ ډوډۍ چې د زیتونو په تېلو باندې غوړه شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_4.mp3', '', 1761754199, 1761754199),
(42081, 'Leviticus 2:5', 'Leviticus', 2, 5, 'که چېرې نذرانه داسې ډوډۍ وي چې په تبۍ باندې پخه شوې وي، هغه دې د داسې ښو اوړو څخه تیاره شي چې د زیتونو تېل ورسره ګډ وي، خو فطیره دې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_5.mp3', '', 1761754199, 1761754199),
(42082, 'Leviticus 2:6', 'Leviticus', 2, 6, 'هغه ټوټې ټوټې کړئ او نور تېل ورباندې واچوئ، دا د غلې دانې یوه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_6.mp3', '', 1761754199, 1761754199),
(42083, 'Leviticus 2:7', 'Leviticus', 2, 7, 'که چېرې نذرانه داسې ډوډۍ وي چې په ارکاره باندې پخه شوې وي، هغه دې د ښو اوړو او د زیتونو د تېلو څخه جوړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_7.mp3', '', 1761754199, 1761754199),
(42084, 'Leviticus 2:8', 'Leviticus', 2, 8, 'د دې شیانو څخه چې کومه د غلې دانې نذرانه جوړه شوې وي، هغه څښتن ته راوړئ او کاهن ته یې وړاندې کړئ، هغه به یې د قربانۍ ځای ته یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_8.mp3', '', 1761754199, 1761754199),
(42085, 'Leviticus 2:9', 'Leviticus', 2, 9, 'کاهن به د هغې څخه یوه برخه واخلي او هغه به د یوې نمونې په توګه چې ټوله څښتن ته وړاندې کیږي، د قربانۍ په ځای باندې وسوځوي. دا یوه داسې نذرانه ده چې بوی یې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_9.mp3', '', 1761754199, 1761754199),
(42086, 'Leviticus 2:10', 'Leviticus', 2, 10, 'د غلې دانې پاتې نذرانه د کاهنانو ده. دا ډېره سپېڅلې ده. دا د هغو نذرانو یوه ډېره سپېڅلې برخه ده چې څښتن ته په اور باندې تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_10.mp3', '', 1761754199, 1761754199),
(42087, 'Leviticus 2:11', 'Leviticus', 2, 11, 'د غلې دانې هغه نذرانې چې څښتن ته یې وړاندې کوئ، په هېڅ یوه کې دې خمیره نه وي. تاسو باید په هغو نذرانو کې چې څښتن ته په اور باندې تیاریږي، هېڅ خمیره یا شات ونه کاروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_11.mp3', '', 1761754199, 1761754199),
(42088, 'Leviticus 2:12', 'Leviticus', 2, 12, 'باید د لومړنیو غلو دانو څخه چې هر کال یې رېبئ څښتن ته یوه نذرانه راوړئ، خو هغه باید د قربانۍ په ځای باندې ونه سوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_12.mp3', '', 1761754199, 1761754199),
(42089, 'Leviticus 2:13', 'Leviticus', 2, 13, 'د غلې دانې په هرې نذرانې باندې مالګه واچوئ، ځکه چې مالګه د خدای او ستاسو په منځ کې د لوظ یوه نښه ده. تاسو باید په خپلو ټولو نذرانو باندې مالګه واچوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_13.mp3', '', 1761754199, 1761754199),
(42090, 'Leviticus 2:14', 'Leviticus', 2, 14, 'کله چې تاسو څښتن ته د لومړنیو رېبل شویو غلو دانو نذرانه راوړئ، نو نینې شوې دانې یا میده اوړه ورته وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_14.mp3', '', 1761754199, 1761754199),
(42091, 'Leviticus 2:15', 'Leviticus', 2, 15, 'په هغې باندې د زیتونو تېل ورزیات کړئ او قیمتي خوشبویي ورباندې واچوئ. دا د غلې دانې یوه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_15.mp3', '', 1761754199, 1761754199),
(42092, 'Leviticus 2:16', 'Leviticus', 2, 16, 'کاهن به د میده اوړو او تېلو یوه برخه د نمونې په توګه د ټولې قیمتي خوشبویۍ سره یوځای د یوې نذرانې په توګه وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus2_verse_16.mp3', '', 1761754199, 1761754199),
(42093, 'Genesis 36:1', 'Genesis', 36, 1, 'دا د عیسو اولاده ده (عیسو د ادوم په نوم هم یادېده.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_1.mp3', '', 1761754199, 1761754199),
(42094, 'Genesis 36:2', 'Genesis', 36, 2, 'عیسو د کنعاني ښځو سره ودونه وکړل: عاده د حیتي ایلون لور، اهولیبامه چې د عنه لور او د حوي صبعون لمسۍ وه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_2.mp3', '', 1761754199, 1761754199),
(42095, 'Genesis 36:3', 'Genesis', 36, 3, 'او بسمه چې د اسماعیل لور او د نبایوت خور وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_3.mp3', '', 1761754199, 1761754199),
(42096, 'Genesis 36:4', 'Genesis', 36, 4, 'عادې الیفاز وزېږاوه او بسمې رعوییل وزېږاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_4.mp3', '', 1761754199, 1761754199),
(42097, 'Genesis 36:5', 'Genesis', 36, 5, 'اهولیبامه یعوش، یعلام او قورح وزېږول. دا د عیسو زامن وو چې په کنعان کې زېږېدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_5.mp3', '', 1761754199, 1761754199),
(42098, 'Genesis 36:6', 'Genesis', 36, 6, 'عیسو خپلې ښځې، زامن، لورګانې او د خپلې کورنۍ ټول غړي او همدارنګه خپلې ټولې رمې او پادې او خپله ټوله شتمني چې په کنعان کې یې لاسته راوړي وو، واخیستل او د خپل ورور یعقوب څخه لږ څه لېرې یې بلې سیمې ته کډه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_6.mp3', '', 1761754199, 1761754199),
(42099, 'Genesis 36:7', 'Genesis', 36, 7, 'هغه لاړ، ځکه هغه ځمکه چې یعقوب او هغه په کې اوسېدل، دومره زیاته نه وه چې دواړه سره یوځای واوسیږي، په دې خاطر چې هغوی زیاتې رمې او پادې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_7.mp3', '', 1761754199, 1761754199),
(42100, 'Genesis 36:8', 'Genesis', 36, 8, 'نو عیسو د ادوم په غرنۍ سیمه کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_8.mp3', '', 1761754199, 1761754199),
(42101, 'Genesis 36:9', 'Genesis', 36, 9, 'دا د ادوم په غرنۍ سیمه کې د ادومیانو د نیکه عیسو اولاده ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_9.mp3', '', 1761754199, 1761754199),
(42102, 'Genesis 36:10', 'Genesis', 36, 10, 'د عیسو د زامنو نومونه دا دي: الیفاز د عیسو د ښځې عاده زوی او رعوییل د عیسو د ښځې بسمې زوی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_10.mp3', '', 1761754199, 1761754199),
(42103, 'Genesis 36:11', 'Genesis', 36, 11, 'د الیفاز زامن: تیمان، اومار، صفو، جعتام او قناز.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_11.mp3', '', 1761754199, 1761754199),
(42104, 'Genesis 36:12', 'Genesis', 36, 12, 'تمناع د عیسو د زوی الیفاز وینځه وه او د هغې څخه د هغه زوی عمالیق پیدا شو. دا د عیسو د ښځې عادې لمسیان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_12.mp3', '', 1761754199, 1761754199),
(42105, 'Genesis 36:13', 'Genesis', 36, 13, 'د رعوییل زامن: نحت، زارح، شمه او مزه. دا د عیسو د ښځې بسمې لمسیان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_13.mp3', '', 1761754199, 1761754199),
(42106, 'Genesis 36:14', 'Genesis', 36, 14, 'اهولیبامه د عنه لور او د صبعون لمسۍ وه چې د هغې څخه د عیسو زامن یعوش، یعلام او قورح پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_14.mp3', '', 1761754199, 1761754199),
(42107, 'Genesis 36:15', 'Genesis', 36, 15, 'د عیسو په اولادې کې دغه قبیلوي مشران وو: د عیسو د مشر زوی الیفاز زامن: تیمان، اومار، صفو، قناز،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_15.mp3', '', 1761754199, 1761754199),
(42108, 'Genesis 36:16', 'Genesis', 36, 16, 'قورح، جعتام او عمالیق. دا په ادوم کې هغه قبیلوي مشران وو چې د الیفاز د اولادې څخه دي او دوی د عادې لمسیان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_16.mp3', '', 1761754199, 1761754199),
(42109, 'Genesis 36:17', 'Genesis', 36, 17, 'د عیسو د زوی رعوییل زامن: نحت، زارح، شمه او مزه. دا په ادوم کې هغه قبیلوي مشران وو چې د رعوییل د اولادې څخه دي. دا د عیسو د ښځې بسمې لمسیان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_17.mp3', '', 1761754199, 1761754199),
(42110, 'Genesis 36:18', 'Genesis', 36, 18, 'د عیسو د ښځې اهولیبامه زامن: یعوش، یعلام او قورح. دا هغه قبیلوي مشران وو چې د عنه د لور یعنې د عیسو د ښځې اهولیبامه د اولادې څخه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis36_verse_18.mp3', '', 1761754199, 1761754199);